__NUXT_JSONP__("/svet/stat/guyana/ubytovani", (function(a,b,c,d,e,f,g,h,i,j,k,l,m,n,o,p,q){return {data:[{tabsLoad:{tabWhatToSee:c,tabPrice:c,tabPeople:c,tabTrip:c,tabContact:c,tabHotel:c,tabNeighboring:h,tabVideos:e,tabArticles:e,tabWallSockets:h,tabChains:1,tabFauna:e,tabFlora:e,tabFoods:5,tabBrands:e},place:[{tld:".gy",name:"Guyana",area:214969,population:786559,slug:j,id_continent:f,information_chatgpt:"\u003Cp\u003EGuyana je stát nacházející se v Jižní Americe. Hraničí s Venezuelou, Brazílií a Surinamem a má přístup k Atlantskému oceánu. Má rozlohu přibližně 215 000 km² a žije zde kolem 800 000 lidí. Hlavním městem Guyany je Georgetown.\u003C\u002Fp\u003E\n\u003Cp\u003EGuyana má bohatou biodiverzitu a část jejího území je pokryta pralesy. V Guyaně se nachází například slavný Guyanský štít, což je jedna z největších vodopádů na světě. Turisté se sem také často sjíždějí za pozorováním želv na pláži v chráněné oblasti Shell Beach.\u003C\u002Fp\u003E\n\u003Cp\u003EGuyana má bohatou historii, která sahá až k původním indiánským obyvatelům. Následně zde působili Nizozemci, Francouzi a Britové, kteří se stali hlavními kolonizátory. Guyana se stala nezávislou v roce 1966.\u003C\u002Fp\u003E\n\u003Cp\u003EHospodářsky je Guyana závislá na těžbě surovin. Největším exportním artiklem jsou diamanty, ale Guyana má také velké zásoby zlata a bauxitu. Důležitým odvětvím je také zemědělství, zejména produkce cukru, rýže a palmy olejné.\u003C\u002Fp\u003E\n\u003Cp\u003EV Guyaně se nachází různorodá kultura a lidé různých národností, včetně Indiánů, Afro-Guyanců, Evropanů a Asijců. Místní obyvatelé jsou obecně velmi přátelští a přívětiví vůči návštěvníkům. \u003C\u002Fp\u003E\n\u003Cp\u003E Nicméně, návštěvníci by měli být obezřetní v některých oblastech Guyany kvůli zvýšené kriminalitě.\u003C\u002Fp\u003E\n\u003Cp\u003ECelkově lze Guyanu charakterizovat jako zajímavou destinaci s bohatou kulturou a přírodou.\u003C\u002Fp\u003E",currency_code:"GYD",currency_name:"dolar",money_prices:[{name:"Taxi (cena za km)",value:k,date_update:a},{name:"Hlavní jídlo",value:1500,date_update:a},{name:"Chleba",value:420,date_update:a},{name:"Mléko",value:k,date_update:a},{name:"Voda (500ml)",value:l,date_update:a},{name:"Espresso",value:360,date_update:a},{name:"Zmrzlina (jeden kopeček)",value:l,date_update:a},{name:"Pivo",value:400,date_update:a},{name:"Krabička cigaret",value:1200,date_update:a},{name:"Big Mac",value:1700,date_update:a},{name:"Coca Cola (500ml)",value:250,date_update:a}],phone_numbers_emergency:[{name:"Mezinárodní tísňová linka",value:m,date_update:b},{name:"Policie",value:m,date_update:b},{name:"Hasiči",value:"912",date_update:b},{name:"Zdravotnická záchranná služba",value:"913",date_update:b}],phone_prefix:"+592",coordinates:[{latitude:"4.8604",longitude:"-58.9302"}],people_religion:[{name:"Křesťanství",value:"63%"},{name:"Hinduismus",value:"24%"},{name:"Islám",value:n},{name:o,value:p}],people_nationality:[{name:"Indiáni",value:"36%"},{name:"Afro-guyanští",value:"30%"},{name:"Východní Indové",value:"20%"},{name:"Mestici",value:n},{name:"Běloši",value:p},{name:o,value:"1%"}],visitors_entry:[{name:"Občanský průkaz",value:"Pro vstup do Guyany není možné použít občanský průkaz. Je potřeba mít platný cestovní pas.",date_update:b},{name:"Cestovní pas",value:"Pro vstup do Guyany je potřeba mít platný cestovní pas.",date_update:b},{name:"Vízum",value:"Pro vstup do Guyany je potřeba mít platné vízum. Občané Evropské unie jsou však osvobozeni od této povinnosti na 90 dní, pokud jejich pobyt neslouží k pracovním nebo studijním účelům.",date_update:b},{name:"Očkování",value:"Pro vstup do Guyany nejsou povinná žádná očkování. Nicméně se doporučuje očkování proti žluté zimnici a hepatitidě A a B.",date_update:b},{name:"Cestovní pojištění",value:"Pro vstup do Guyany není nutné mít cestovní nebo zdravotní pojištění, ale je doporučeno mít je, aby se zajistilo krytí případných zdravotních nákladů v zemi.",date_update:b},{name:"Bezpečností situace",value:"Guyana má vysokou míru kriminality, zejména v hlavním městě Georgetownu a v pobřežních oblastech. Návštěvníci by měli být obezřetní a dodržovat základní bezpečnostní opatření, jako je vyhýbání se osamělým oblastem a nočním procházkám v nebezpečných oblastech.",date_update:b},{name:"Další informace",value:"Při cestování do Guyany je důležité věnovat pozornost místním zvyklostem a tradicím. Například, když navštívíte vesnice domorodých obyvatel, je vhodné se zeptat na svolení a respektovat místní zvyklosti. V zemi se používá angličtina a místní měna je guyanský dolar (GYD).",date_update:b}],type_place:q,id_image_cover:i,id_image_hero:i,id_city_main:908,affiliate:[{name:"booking",value:c}],mpz:"GY",alerts:[{name:"Venezuelané chtějí převzít kontrolu nad částí Guyany",text:g,type:"orange",author:"1",date_create:"2023-12-05",date_update:g,date_start:g,date_end:g}],zoom:[{google:6,booking:7}],ids_neighboring_countries:[{id:31},{id:207},{id:238}],organization:[],apps:[],links:[],information_author:[],seo_tags:[],language_phrases:[],wall_sockets:d,id:94,facts_place:d,created_at:"2023-12-27T16:33:10.517062+00:00",updated_at:"2023-12-27T17:07:31.480426+00:00",name_original:d}],imagePlace:[{id:i,name:j,source:"\u002Fworld\u002Fstates\u002F",type:q,author:"pixabay.com",created_at:"2023-05-02T18:49:47.851894+00:00",updated_at:"2023-12-27T20:42:18.520959+00:00"}],placeContinent:[{id:f,slug:"jizni-amerika",name:"Jižní Amerika",area:17840000,population:430000000,population_density:24.11,number_states:12,information_chatgpt:"\u003Cp\u003EJižní Amerika je kontinent nacházející se v jižní polovině zeměkoule. Je druhým největším kontinentem v Americe a čtvrtým největším kontinentem na světě. Rozprostírá se od Karibiku na severu po Průliv Drakea na jihu, což představuje přibližně 7 000 kilometrů. Tento kontinent obývá více než 420 milionů lidí a skládá se ze 12 různých států.\u003C\u002Fp\u003E\n\u003Cp\u003EJižní Amerika má velmi rozmanitou geografii. Na západní straně kontinentu se nachází Andské pohoří, které je nejdelší pohoří na světě a táhne se přes 7 zemí. Na východní straně se nachází rozsáhlé deštné pralesy a oblasti savan. Kromě toho se zde nachází také největší řeka na světě - Amazonka, která má neuvěřitelný vliv na floru a faunu regionu.\u003C\u002Fp\u003E\n\u003Cp\u003EJižní Amerika má také velmi bohatou historii a kulturu. Před příchodem Evropanů byla tato oblast domovem mnoha starověkých civilizací, jako jsou Inkové, Mayové a Aztékové. Tyto civilizace zanechaly pozoruhodné památky, jako jsou Machu Picchu, Chichén Itzá a Tiahuanaco. Později byla tato oblast ovlivněna kolonizací ze strany Španělska a Portugalska, což má dodnes vliv na jazyky, kulturu a způsob života.\u003C\u002Fp\u003E\n\u003Cp\u003EJižní Amerika je také velmi oblíbenou turistickou destinací. V Argentině a Brazílii se nacházejí největší vodopády světa - Iguazú a Niagarské vodopády. Peru je domovem Machu Picchu, jedné z nejnavštěvovanějších archeologických lokalit na světě. Kromě toho jsou zde také krásné pláže, horské túry, národní parky a další přírodní krásy.\u003C\u002Fp\u003E\n\u003Cp\u003EV Jižní Americe se také nachází mnoho kulturních festivalů a událostí. Například karnevaly v Rio de Janeiru a Buenos Aires jsou světoznámé pro svou atmosféru a pestrost barev. Také zde můžete ochutnat mnoho unikátních kulinářských specialit, jako jsou arepas v Kolumbii, ceviche v Peru a asado v Argentině.\u003C\u002Fp\u003E\n\u003Cp\u003EZkrátka, Jižní Amerika je kontinent plnýkrás, kulturního bohatství a přírodních divů. Mnoho turistů sem přijíždí za poznáním exotického prostředí, ale také kvůli možnostem dobrodružství a sportovních aktivit. Například v Brazílii je oblíbená plážová fotbalová hra zvaná futevôlei, zatímco v Chile si turisté užívají snowboardování na Andách.\u003C\u002Fp\u003E\n\u003Cp\u003EJižní Amerika má také své problémy, jako je sociální nerovnost, kriminalita a korupce. Některé oblasti jsou považovány za nebezpečné pro turisty, takže je třeba být obezřetní a využívat služby kvalitních turistických průvodců.\u003C\u002Fp\u003E\n\u003Cp\u003EZávěrem lze říci, že Jižní Amerika je fascinující kontinent, který nabízí mnoho příležitostí pro poznání, zážitky a dobrodružství. Bez ohledu na to, jestli plánujete návštěvu kvůli přírodě, kultuře nebo jen na odpočinek na pláži, určitě nebudete zklamáni.\u003C\u002Fp\u003E",coordinates:[{latitude:-14.235004,longitude:-51.92528}],type_place:"continent",id_image_cover:f,id_image_hero:f,zoom:[{google:f,booking:h}],information_author:d,seo_tags:d,created_at:"2023-12-27T16:35:37.460505+00:00",updated_at:"2023-12-27T17:07:06.531847+00:00",name_original:d}]}],fetch:{},mutations:[]}}("06-2021","05-2023",true,null,0,2,"",3,264,"guyana",300,230,"911","7%","Ostatní","6%","state")));